DROP TABLE IF EXISTS `biz_external_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_external_data` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `system_code` varchar(64) NOT NULL COMMENT '外部系统编码',
  `external_id` varchar(128) NOT NULL COMMENT '外部系统数据ID',
  `data_type` varchar(64) NOT NULL COMMENT '数据类型: EVENT/POPULATION/MERCHANT',
  `raw_data` json DEFAULT NULL COMMENT '原始数据',
  `normalized_data` json DEFAULT NULL COMMENT '标准化后数据',
  `sync_status` varchar(16) DEFAULT 'PENDING' COMMENT '同步状态: PENDING/SYNCED/FAILED',
  `linked_business_id` bigint DEFAULT NULL COMMENT '关联的业务ID',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_external_data` (`system_code`,`external_id`,`data_type`),
  KEY `idx_biz_external_data_status` (`sync_status`)
) ENGINE=InnoDB AUTO_INCREMENT=1173 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='外部数据缓存';
