CREATE TABLE `biz_process_instance_node` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `process_instance_id` bigint NOT NULL,
  `template_node_id` bigint DEFAULT NULL,
  `node_key` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `node_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `node_order` int NOT NULL,
  `approve_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `role_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Node execution status',
  `assignee_user_id` bigint DEFAULT NULL,
  `assignee_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `handled_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `cycle_no` int NOT NULL DEFAULT '1',
  `is_current` tinyint NOT NULL DEFAULT '1',
  `node_mode` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL DEFAULT 'SINGLE',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `fk_biz_process_instance_node_assignee` (`assignee_user_id`) USING BTREE,
  KEY `idx_biz_process_instance_node_status` (`status`) USING BTREE,
  KEY `idx_biz_process_instance_node_current` (`process_instance_id`,`is_current`,`node_order`) USING BTREE,
  KEY `idx_biz_process_instance_node_template_node` (`template_node_id`) USING BTREE,
  KEY `idx_biz_process_instance_node_assignee` (`process_instance_id`,`assignee_user_id`),
  CONSTRAINT `fk_biz_process_instance_node_assignee` FOREIGN KEY (`assignee_user_id`) REFERENCES `sys_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_biz_process_instance_node_instance` FOREIGN KEY (`process_instance_id`) REFERENCES `biz_process_instance` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
