DROP TABLE IF EXISTS `biz_work_order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_work_order` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `work_order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `source_event_id` bigint NOT NULL,
  `status` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'WorkOrderStatus: handling to close lifecycle',
  `assignee_user_id` bigint DEFAULT NULL,
  `assignee_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `dispatcher_user_id` bigint DEFAULT NULL,
  `dispatcher_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `accepted_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `close_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `process_instance_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `work_order_no` (`work_order_no`) USING BTREE,
  UNIQUE KEY `source_event_id` (`source_event_id`) USING BTREE,
  KEY `fk_biz_work_order_assignee` (`assignee_user_id`) USING BTREE,
  KEY `fk_biz_work_order_dispatcher` (`dispatcher_user_id`) USING BTREE,
  KEY `idx_biz_work_order_status` (`status`) USING BTREE,
  KEY `idx_biz_work_order_process_instance` (`process_instance_id`) USING BTREE,
  KEY `idx_biz_work_order_assignee_status` (`assignee_user_id`,`status`),
  KEY `idx_biz_work_order_status_created` (`status`,`created_at` DESC),
