  `grid_id` bigint DEFAULT NULL COMMENT '所属网格ID',
  `name` varchar(100) COLLATE utf8mb4_german2_ci NOT NULL COMMENT '姓名',
  `id_card` varchar(32) COLLATE utf8mb4_german2_ci DEFAULT NULL COMMENT '身份证号',
  `phone` varchar(32) COLLATE utf8mb4_german2_ci DEFAULT NULL COMMENT '联系电话',
  `gender` varchar(8) COLLATE utf8mb4_german2_ci DEFAULT NULL COMMENT '性别',
  `birthday` date DEFAULT NULL COMMENT '出生日期',
  `household_type` varchar(32) COLLATE utf8mb4_german2_ci DEFAULT NULL COMMENT '户籍类型: LOCAL=本地 RENTAL=租住 FLOATING=流动',
  `address` varchar(255) COLLATE utf8mb4_german2_ci DEFAULT NULL COMMENT '居住地址',
