DROP TABLE IF EXISTS `sys_audit_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `table_name` varchar(64) NOT NULL COMMENT '操作的表名',
  `record_id` varchar(64) NOT NULL COMMENT '记录ID',
  `operation_type` varchar(16) NOT NULL COMMENT '操作类型: CREATE/UPDATE/DELETE',
  `old_values` json DEFAULT NULL COMMENT '变更前的值',
  `new_values` json DEFAULT NULL COMMENT '变更后的值',
  `changed_fields` json DEFAULT NULL COMMENT '变更的字段列表',
  `operator_id` bigint DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) DEFAULT NULL COMMENT '操作人姓名',
  `operation_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_table_record` (`table_name`,`record_id`),
  KEY `idx_operation_time` (`operation_time`),
  KEY `idx_operator` (`operator_id`),
  KEY `idx_audit_log_time` (`operation_time`)
) ENGINE=InnoDB AUTO_INCREMENT=333 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='数据变更审计日志';
/*!40101 SET character_set_client = @saved_cs_client */;

