CREATE TABLE `sys_party_task` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `task_title` varchar(200) NOT NULL COMMENT '任务标题',
  `task_type` varchar(32) NOT NULL COMMENT '任务类型: PATROL巡查 / MEDIATION矛盾调解 / VISIT走访 / MEETING三会一课 / PUBLICITY政策宣传 / OTHER其他',
  `description` varchar(500) DEFAULT NULL COMMENT '任务描述',
  `grid_id` bigint DEFAULT NULL COMMENT '所属网格',
  `assigned_member_id` bigint DEFAULT NULL COMMENT '指派党员ID',
  `deadline` date DEFAULT NULL COMMENT '截止日期',
  `status` varchar(16) DEFAULT 'PENDING' COMMENT '状态: PENDING待领办 / ACCEPTED已领办 / COMPLETED已完成 / CANCELLED已取消',
  `created_by` bigint DEFAULT NULL COMMENT '创建人',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_grid` (`grid_id`),
  KEY `idx_member` (`assigned_member_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='党建任务下沉';
